import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return root

def rob_brute(root):
    if not root: return 0
    v = root.v
    ll = root.l or T(0)
    rr = root.r or T(0)
    take = v + (rob_brute(ll.l) if ll.l else 0) + (rob_brute(ll.r) if ll.r else 0) + (rob_brute(rr.l) if rr.l else 0) + (rob_brute(rr.r) if rr.r else 0)
    skip = rob_brute(root.l) + rob_brute(root.r)
    return max(take, skip)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    arr = data[1:1 + n]
    root = build(arr)
    print(rob_brute(root))

